lass=&#34;keyword&#34;&gt;OR&lt;/span&gt; (id &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;number&#34;&gt;26&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;AND&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;#x27;1&amp;#x27;&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;string&#34;&gt;&amp;#x27;1&amp;#x27;&lt;/span&gt;)    &lt;span class=&#34;keyword&#34;&gt;and&lt;/span&gt;的优先级大于&lt;span class=&#34;keyword&#34;&gt;or&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;#最终&lt;span class=&#34;literal&#34;&gt;false&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;OR&lt;/span&gt; (&lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;AND&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;) → &lt;span class=&#34;literal&#34;&gt;true&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
